using System;
using System.Collections.Generic;

namespace Loja.Billing;

/// <summary>Cobrança de assinaturas.</summary>
public sealed class BillingService
{
    private readonly IPaymentGateway _gateway;

    public BillingService(IPaymentGateway gateway)
    {
        _gateway = gateway;
    }

    public Invoice Charge(Subscription subscription, DateOnly cycle)
    {
        var amount = subscription.Plan.MonthlyPrice;
        var invoice = Invoice.For(subscription, cycle, amount);
        _gateway.Capture(invoice);
        return invoice;
    }

    public void ChargeRecurring(IEnumerable<Subscription> active, DateOnly cycle)
    {
        foreach (var subscription in active)
        {
            if (subscription.IsPaused) continue;
            Charge(subscription, cycle);
        }
    }

    public Refund RefundLastInvoice(Subscription subscription)
    {
        var last = subscription.Invoices[^1];
        return _gateway.Refund(last);
    }
}

