from decimal import Decimal


def calcular_juros(saldo: Decimal, taxa_mensal: Decimal, meses: int) -> Decimal:
    """Juros compostos sobre o saldo em atraso."""
    return saldo * ((1 + taxa_mensal) ** meses - 1)


def aplicar_multa(saldo: Decimal) -> Decimal:
    """Multa fixa de dois por cento sobre o saldo devedor."""
    return saldo * Decimal("0.02")


class Inadimplencia:
    """Agrupa cobranças vencidas por cliente."""

    def __init__(self) -> None:
        self.vencidas: dict[str, list[Decimal]] = {}

    def registrar(self, cliente: str, valor: Decimal) -> None:
        self.vencidas.setdefault(cliente, []).append(valor)

import { useEffect, useState } from 'react';

export type InvoiceRow = { id: string; total: number; status: 'open' | 'paid' };

export function useInvoices(customerId: string) {
  const [rows, setRows] = useState<InvoiceRow[]>([]);
  useEffect(() => {
    let active = true;
    fetch(`/api/customers/${customerId}/invoices`)
      .then((response) => response.json())
      .then((data: InvoiceRow[]) => {
        if (active) setRows(data);
      });
    return () => {
      active = false;
    };
  }, [customerId]);
  return rows;
}

export function formatTotal(total: number): string {
  return total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}
